<?php
declare(strict_types=1);
session_start();
$error='';
try { require_once __DIR__.'/bot.php'; require_once __DIR__.'/registered-users.php'; } catch (Throwable $e) { http_response_code(500); echo '<!doctype html><meta charset="utf-8"><title>Keddy Bot Error</title><body style="font-family:system-ui;background:#090b10;color:#fff;padding:30px"><h1>🤖 Keddy Bot</h1><p>Startup error:</p><pre style="white-space:pre-wrap;background:#2d1418;padding:15px;border-radius:8px">'.htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8').'</pre></body>'; exit; }
if(empty($_SESSION['keddy_heartbeat_token'])) $_SESSION['keddy_heartbeat_token']=bin2hex(random_bytes(24));
$heartbeatToken=$_SESSION['keddy_heartbeat_token'];
if($_SERVER['REQUEST_METHOD']==='POST') try { $a=$_POST['action']??''; if($a==='start') startS(); elseif($a==='stop') stopS(); elseif($a==='next') nextS(); } catch(Throwable $e) { $error=$e->getMessage(); }
$connected=!!gv('oauth'); $botConnected=!!gv('bot_oauth'); $lastErr=gv('bot_last_send_error','');
function h($x):string{return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Keddy Bot</title><style>body{margin:0;background:#090b10;color:#f4f5f7;font:15px system-ui;padding:24px}.box{max-width:900px;margin:auto;background:#10131a;border:1px solid #252a35;border-radius:12px;padding:24px}.btn{padding:10px 14px;border:0;border-radius:7px;background:#7c5cff;color:#fff;font-weight:700;cursor:pointer}.err{background:#2d1418;border:1px solid #673039;color:#ffb9c0;padding:12px;border-radius:8px;margin:14px 0}</style></head><body><main class="box"><h1>🤖 Keddy Bot Dashboard</h1><p>YouTube: <b><?= $connected?'Connected':'Not connected' ?></b> · Keddy Bot BTS: <b><?= $botConnected?'Connected':'Not connected' ?></b></p><?php if($error):?><div class="err">⚠️ <?=h($error)?></div><?php endif;?><?php if($lastErr):?><div class="err">Last bot send error: <?=h($lastErr)?></div><?php endif;?><div style="display:flex;gap:8px;flex-wrap:wrap"><?php if(!$connected):?><a class="btn" href="oauth.php">Connect YouTube</a><?php else:?><form method="post"><input type="hidden" name="action" value="start"><button class="btn">▶ Start Keddy</button></form><form method="post"><input type="hidden" name="action" value="stop"><button class="btn">■ Stop</button></form><?php endif;?><?php if(!$botConnected):?><a class="btn" href="bot-oauth.php">Connect Keddy Bot BTS</a><?php endif;?></div><p style="color:#8d96a8;margin-top:25px">Heartbeat: every 15 seconds.</p></main><script>const token=<?=json_encode($heartbeatToken)?>;const tick=()=>fetch('cron.php?heartbeat=1&token='+encodeURIComponent(token)+'&_='+Date.now(),{cache:'no-store',credentials:'same-origin'}).catch(()=>{});tick();setInterval(tick,15000);</script></body></html>